  (12, 'ulasan_wfc_testing_5000.csv', 18621, 0, 'berhasil', 'Klasifikasi manual; accuracy=0.652227; macro-F1=0.518787', 1, '2026-10-26 20:37:38'),
  (13, 'ulasan_wfc_final.csv', 194923, 0, 'berhasil', 'Klasifikasi manual; accuracy=0.679340; macro-F1=0.585245', 1, '2026-10-27 02:29:22'),
  (14, 'ulasan_wfc_final.csv', 229889, 0, 'berhasil', 'Klasifikasi manual; accuracy=0.698306; macro-F1=0.556551', NULL, '2026-10-27 03:05:27'),
  (15, 'ulasan_wfc_final.csv', 229889, 0, 'berhasil', 'Klasifikasi manual; accuracy=0.812507; macro-F1=0.621727', 1, '2026-10-29 08:03:09'),
  (16, 'dataset_Nov_preprocessed.csv', 1923, 0, 'berhasil', 'Klasifikasi manual; accuracy=0.870091; macro-F1=0.869858', NULL, '2026-11-18 10:13:56'),
  (17, 'dataset_Nov_preprocessed.csv', 1923, 0, 'berhasil', 'Klasifikasi manual; accuracy=0.903323; macro-F1=0.903280', NULL, '2026-11-18 12:17:51');
INSERT INTO validasi_v4 ("id", "urutan", "sub_kalimat", "teks_ulasan", "rating", "aspek", "sentimen", "status", "sentimen_koreksi", "catatan", "diperiksa_pada") VALUES
  (101, 1, 'Suasanya tenang bgt', 'Sarapan pagi nya mantab banget. Porsi pas untuk sarapan pagi. Suasanya tenang bgt, bisa ngeteh atau ngopi bersama pasangan. The best dech untuk harmoni sarapan paginya. Bikin nagih dan ngangenin Lainnya', 5, 'suasana', 'positif', 'benar', NULL, NULL, '2026-10-26 00:23:50'),
  (102, 2, 'Cafedi dalam Hotel dengan konsep unik', 'Cafedi dalam Hotel dengan konsep unik. pelayanan cafe ini bagus, makanan layak!', 5, 'suasana', 'positif', 'benar', NULL, NULL, '2026-10-26 00:23:50'),
  (103, 3, 'Saya suka suasana tokonya', 'Saya suka suasana tokonya, pelayanannya, dan tempatnya. Makanan dan minumannya biasa saja.', 4, 'suasana', 'positif', 'benar', NULL, NULL, '2026-10-26 00:23:50'),
  (104, 4, 'yaitu nasi di takir (wadah bambu berbentuk segitiga) separuh telur bumbu kecap yg meresap', 'Saya menikmati nasi liwet, yaitu nasi di takir (wadah bambu berbentuk segitiga) separuh telur bumbu kecap yg meresap. Mirip telurnya gudeg. Sayur manisa, putih telur. Sambal. Harganya Rp 15.000. Dan segelas es teh Rp 5.000. Hanya ada pagi … Lainnya', 5, 'makanan_minuman', 'positif', 'salah', 'netral', 'dia cuma nyeritain yg dipesen gaada bilang enak ato apa gitu', '2026-10-26 00:23:50'),
  (105, 5, 'Tempat yang unik dan penuh nostalgia', 'Tempat yang unik dan penuh nostalgia! Kafe ini mengusung tema boneka vintage yang sangat menggemaskan. Setiap sudutnya didekorasi dengan boneka-boneka klasik, memberikan suasana hangat dan cozy. Makanan dan minumannya enak, cocok buat santai atau kumpul bareng teman. Cocok juga untuk foto-foto Instagram! Pasti akan balik lagi ke sini."', 5, 'suasana', 'positif', 'benar', NULL, NULL, '2026-10-26 00:23:50'),
  (106, 6, 'tempat nya luas Lainnya', 'Suka banget sama ambience disini jadi semangat nugas, pastry nya enak, minuman nya oke dan tempat nya luas Lainnya', 5, 'suasana', 'positif', 'benar', NULL, NULL, '2026-10-26 00:23:50'),
  (107, 7, 'Tempat outdoor nya juga cakep', 'Tempatnya enak sih, nyaman, rapi, bersih, apik, enak buat tempat kerja juga, varian cemilan dan minumannya juga banyaaak, harganya standar, gk terlalu mahal. Tapi minusnya ramenya gak karu2an jd kalo tempatnya penuh, gabisa buat duduk dan kerja. Tempat outdoor nya juga cakep, tp kalo hujan gabisa dipake. Overall cukup puas sama tempatnya. Kalo gak terlalu rame, bs jd tempat kerja yg mantep deh', 5, 'suasana', 'positif', 'benar', NULL, NULL, '2026-10-26 00:23:50'),
  (108, 8, 'tempatnya nyamannn polll', 'Kasir serta pegawainya sangat ramah sekali, tempatnya nyamannn polll dan sangat bersih sekaliii sukakk saya, pelayanannya super cepat, cocok untuk bersantaii sih menurutku Lainnya', 5, 'suasana', 'positif', 'benar', NULL, NULL, '2026-10-26 00:23:50'),
  (109, 9, 'Area nya luas', 'cocok buat kesini sama teman teman, Area nya luas, pelayanan mantap dan cepat', 5, 'suasana', 'positif', 'benar', NULL, NULL, '2026-10-26 00:23:50'),
  (110, 10, 'pemandangan di lvl', 'Pengalaman yang sangat berkesan, berlibur di malang dan berkuliner di Lafayette, resto yang sangat peduli pada batasan2 syariat, musholla yang perfect dan sangat nyaman, mudah diakses karna lokasinya di pusat kota, menu2 yang beragam dan worth it, pemandangan di lvl. 3 juga epik, bangunannya yang merupakan bangunan bekas jaman penjajahan menghadirkan vibes VOC versi halal, yang kurang cuman lahan parkirnya aja, saran saya bangun parkir basement kalo dibolehin.', 5, 'suasana', 'positif', 'salah', 'negatif', NULL, '2026-10-26 00:23:50'),
  (111, 11, 'pelayanan top', 'Enaak..pelayanan top..parkir mobil ada', 5, 'pelayanan', 'positif', 'benar', NULL, NULL, '2026-10-26 00:23:50'),
  (112, 12, 'terutama kopi roketto', 'Cocok buat nongkrong. Bener2 cafe yg ideal. Kopinya enak, terutama kopi roketto.', 5, 'makanan_minuman', 'positif', 'benar', NULL, NULL, '2026-10-26 00:23:50'),
  (113, 13, 'pelayanan nya juga cepat bestt pokoknya', 'minuman dan makanannya enak pake bangeetttt, pelayanan nya juga cepat bestt pokoknya', 5, 'pelayanan', 'positif', 'benar', NULL, NULL, '2026-10-26 00:23:50'),
  (114, 14, 'dia happy banget sama rasa dan bentuknya', 'Nyaman banget sebenarnya untuk nongkrong lama2, tapi menu beratnya mungkin bisa diperbanyak yaa kak, sama cemilannya hehe. kesini nyobain mie apaa gitu ya, sama singapore toast box. untuk toast boxnya jadi andalan kalau anakku minta reward, dia happy banget sama rasa dan bentuknya. pasti habis. Cuman untuk mie nya aku salah pesan kayaknya. jadi itu mienya kebanyakan saos tomatnya jadi cenderung asemm, gurihnya ketutup. juga mungkin bisa ditambah cabe yaa, jadi bisa lebih seimbang. kopinya enak, es milonya jg enak. pelayanannya juga perfecto.', 5, 'makanan_minuman', 'positif', 'benar', NULL, NULL, '2026-10-26 00:23:50'),
  (115, 15, 'cuman aku gatau kenapa ko aku ga dilayani', 'pls ka mohon diperbaiki lagi pelayanannya, aku pesen 4 makanan yang dateng cuma 3 dan itu lama banget jaraknya, dan anehnya lagi makanan yang aku pesen sebenernya ada di display, cuman aku gatau kenapa ko aku ga dilayani, pdhl suda membayar … Lainnya', 1, 'pelayanan', 'negatif', 'benar', NULL, NULL, '2026-10-26 00:23:50'),
  (116, 16, 'Kalo untuk pemandangan aih bangusnya di taman', 'Tempat nongkrong kekinian. Ada 5 ground dilengkapi juga dengan arena bermain anak, mushola dan toilet. Paling enak kesini malem. Pemandangannya cantik banyak lampu2 gantung seperti konsep rustik. bisa pilih tempat duduk di taman (terbuka) atau tempat duduk yg tertutup kanopi. Kalo untuk pemandangan aih bangusnya di taman. Tapi kalo kamu bawa anak kecil baiknya jangan duduk di taman karna banyak nyamuk makanannya lumayan enak dan variatif', 4, 'suasana', 'netral', 'benar', NULL, NULL, '2026-10-26 00:23:50'),
  (117, 17, 'Btw menu kopinya lengkap dan bervariasi', 'Nice place to drink coffee! Btw menu kopinya lengkap dan bervariasi. Menu non coffeenya juga tersedia. Snack dan dessertnya juga recommended. Oh ya, fasilitasnya lengkap, dari outdoor dan indoor space, toilet, musholla, bahkan ada … Lainnya', 5, 'makanan_minuman', 'positif', 'benar', NULL, NULL, '2026-10-26 00:23:50'),
  (118, 18, 'minumannya: selalu enak', 'Beberapa kali ke sini, puas banget sama makanan dan minumannya: selalu enak! Sepertinya cemilannya memang enak-enak semua. Tempatnya ada di lantai dua distro Sch daerah Soekarno Hatta. Tempatnya memang nggak terlalu besar, tapi desain … Lainnya', 5, 'makanan_minuman', 'positif', 'benar', NULL, NULL, '2026-10-26 00:23:50'),
  (119, 19, 'Makananya enak tergolong murah kalau dibandingan dengan harganya', 'Tempatnya nyaman banget. Makananya enak tergolong murah kalau dibandingan dengan harganya. Kopinya juga enak dan harganya terjangkau. Cocok untuk nongki2 dan rasan2', 5, 'makanan_minuman', 'positif', 'benar', NULL, NULL, '2026-10-26 00:23:50'),
  (120, 20, 'coffee nya terlalu pahit', 'Makananya lumayan, coffee nya terlalu pahit, kayak americano padahal pesan mocha, untuk makanannya 7/10 lah, tempatnya riuh banget full terus, tapi nyaman banget, next kesini lagi Lainnya', 4, 'makanan_minuman', 'negatif', 'benar', NULL, NULL, '2026-10-26 00:23:50'),
  (121, 21, 'kalo memang self service mungkin bisa di berikan tulisan + diingatkan agar pengunjung lain lebih aware', 'mungkin untuk kebersihannya kurang ya karena lantainya agak kotor dan kalo memang self service mungkin bisa di berikan tulisan + diingatkan agar pengunjung lain lebih aware', 4, 'pelayanan', 'netral', 'salah', 'negatif', 'agar pengunjung lebih aware itu berarti service disana gak komunikatif dan kurang', '2026-10-26 01:23:54'),
  (122, 22, 'Enak buat meeting klien', 'Enak buat meeting klien', 5, 'makanan_minuman', 'positif', 'salah', 'positif', 'buat meeting klien itu termasuk ke tempat" wfc gitu bukan makanan', '2026-10-26 01:23:54'),
  (123, 23, 'SEPI NYAMANN', 'HE REK SUMPAA, INI TEMPAT WORTH ITTTTTT BGTT WALAUPUN NYEMPILLL! SUASANA OKE, MAKANAN OKE, MINUMAN OKEEE POKO E SUKAAA, SEPI NYAMANN. tpi next lebih bagus sediain baby chair kakk', 5, 'suasana', 'positif', 'benar', NULL, NULL, '2026-10-26 01:23:54'),
  (124, 24, 'dan pastinya bersih', 'Utk nongki, nugas, wfc cocok banget minuman dan makanan enak, tempat luas, nyaman, dan pastinya bersih', 5, 'kebersihan', 'positif', 'benar', NULL, NULL, '2026-10-26 01:23:54'),
  (125, 25, 'Tteobokkinya enak dan pedasnya cukup', 'My new fav korean resto in town! Tteobokkinya enak dan pedasnya cukup, gimmarinya pas dan enak bgt dimakan bareng tteoknya (crispynya awet), tuna kimbabnya juga enak. Overall enak semua, jadi penasaran coba menu lainnya next time. 👍🏻 Untuk harga standard ya sesuai yang didapatkan. Kebersihan baik, staff standard, parkir mobil ada di pinggir jalan tersedia cukup banyak, parkir motor di depan resto luas juga. Untuk ke sini kalau naik mobil besar memang agak sempit, tapi jalannya overall masih oke. Bakal ke sini lagi next time 👍🏻', 5, 'makanan_minuman', 'positif', 'benar', NULL, NULL, '2026-10-26 01:23:54'),
  (126, 26, 'Kesini pas malem minggu jam 10 malem croissant nya udah tinggal dikit banget pilihan nya jadi ga jadi beli', 'Kesini pas malem minggu jam 10 malem croissant nya udah tinggal dikit banget pilihan nya jadi ga jadi beli. Caramel mochiato nya enak. Tempatnya cocok buat nugas ataupun work from caffe, colokan banyak banget jadi tenang kalo pas batre habis m. Toilet juga nyaman bersih. Nice🫶🏻', 5, 'makanan_minuman', 'positif', 'salah', 'negatif', 'jadi gabisa beli brrti kurang dong', '2026-10-26 01:23:54'),
  (127, 27, 'penyajian bersih', 'Suasana cafe nyaman, karyawan ramah, menu bervariasi, penyajian bersih, banyak pilihan tempat duduk (indoor atau outdoor),', 4, 'kebersihan', 'positif', 'benar', NULL, NULL, '2026-10-26 01:23:54'),
  (128, 28, 'tapi wifi e troble apa gimana ya kak', 'Enak pol, tapi wifi e troble apa gimana ya kak? kok gabisa dipakai', 2, 'fasilitas_wfc', 'netral', 'salah', 'negatif', 'wifi trouble / troble itu brrti kekurangan dong', '2026-10-26 01:23:54'),
  (129, 29, 'Sesuai lah sama rasa makanan dan pelayanannya', 'Agak pricey tp gapapa sekali kali. Sesuai lah sama rasa makanan & pelayanannya, juga kebersihan dan kenyamanan tempatnya. Lainnya', 5, 'makanan_minuman', 'positif', 'benar', NULL, NULL, '2026-10-26 01:23:54'),
  (130, 30, 'sama donat kentangnya jg enak', 'Suasananya ramai kopi beernya enak sampai beli lg buat di rumah, sama donat kentangnya jg enak, brownies nya tebel end murce Lainnya', 5, 'makanan_minuman', 'positif', 'benar', NULL, NULL, '2026-10-26 01:23:54'),
  (131, 31, 'Cafe buat pecinta kucing yang pengen nongkrong sambil main dengan kucing-kucing yang jinak lucu dan terawat baik', 'Cafe buat pecinta kucing yang pengen nongkrong sambil main dengan kucing-kucing yang jinak lucu dan terawat baik. Ruangannya bersih, area duduk lumayan luas ada 2 lantai. Saya rasa perlu ditambahkan kipas angin baik di lantai 1 maupun 2. Pengunjung tidak diperkenankan membawa makanan dari luar. Area parkir terbatas di pinggir jalan. Makanan dan minuman enak, harga standar. Menerima pembayaran dengan cash, QRIS atau token.', 4, 'suasana', 'netral', 'salah', 'positif', 'terawat brrti positif dong', '2026-10-26 01:23:54'),
  (132, 32, 'harga menu di kisaran 15k-35k', 'Lokasinya di pusat kota malang, tepatnya di depan alun2 tugu malang atau seberang balaikota malang... konsepnya semi outdoor... cukup lega.... varian menu cukup banyak.. untuk makanan berat ada olahan nasi goreng, bakmi, rice bowl dll... untuk snack nya ada kentang goreng, pisang bakar, singkong, lumpia, risol dll... untuk minumannya ada kopi dan non kopi... aneka juice, float dll... harga menu di kisaran 15k-35k.. dan ada live music juga...', 4, 'makanan_minuman', 'netral', 'benar', NULL, NULL, '2026-10-26 01:23:54'),
  (133, 33, 'Yang indoor suasana seperti rumahan', 'Tempat cukup unik bisa ngopi di pinggir rel kereta api.. kadang bisa ngelihat kereta lewat, tapi harus tetap hati hati... Ada wifi, toilet juga ada... Yang indoor suasana seperti rumahan, cuma agak sempit, tapi tetep recommended laaah 👍👍👍👍🔥🔥 …', 5, 'suasana', 'positif', 'salah', 'negatif', 'konteksnya negatif soalnya rumahan yg dimaksud sempit', '2026-10-26 01:23:54'),
  (134, 34, 'Enak buat nongkrong malem hari', 'Enak buat nongkrong malem hari', 5, 'suasana', 'positif', 'benar', NULL, NULL, '2026-10-26 01:23:54'),
  (135, 35, 'Parkir ada di gedung sebelahnya', 'Caffe dengan salah satu pemandangan terbaik menghadap Tugu Malang. Suasananya syahdu saat sore dan malam. Minuman harganya sedikit lebih mahal tapi makanannya termasuk murah. Parkir ada di gedung sebelahnya. Pembayaran busa tunai atau non tunai dibayar di depan dulu.', 5, 'fasilitas_wfc', 'positif', 'benar', NULL, NULL, '2026-10-26 01:23:54'),
  (136, 36, 'dan rasa nya juga kurang endeus', 'Untuk tempat oke lah, esthetic buat foto2, unyu banget pake konsep pink di setiap sudut nya, tempat makan dan minum nya unyu bau2 korea gitu, tempat nya ada indoor juga outdoor nya yg sama2 nyaman juga, parkir juga luas muat buat mobil. Untuk menu makanan nya menurut ku kurang worth it sih dengan harga segitu, dan rasa nya juga kurang endeus, kalo minuman oke sih masih relate. Pelayanan juga baik, serving juga gak lama-lama banget.', 3, 'makanan_minuman', 'netral', 'salah', 'negatif', 'kurang endus brrti negatif', '2026-10-26 01:23:54'),
  (137, 37, 'punya rasa spesial', 'Kopinya oke. Pun snacknya, punya rasa spesial. Recommended', 5, 'makanan_minuman', 'positif', 'benar', NULL, NULL, '2026-10-26 01:23:54'),
  (138, 38, 'menunya juga murah murah cocok buat pelajar', 'Tempat nya enak buat tugas, menunya juga murah murah cocok buat pelajar. Tempatnya luas banyak colokan + wifi nya mantep Lainnya', 5, 'harga', 'positif', 'benar', NULL, NULL, '2026-10-26 01:23:54'),
  (139, 39, 'es kopi pertama kayaknya di malang punya ciri khas tersendiri', 'es kopi pertama kayaknya di malang punya ciri khas tersendiri', 5, 'makanan_minuman', 'positif', 'benar', NULL, NULL, '2026-10-26 01:23:54'),
  (140, 40, 'tempat indoor (ber AC) dan outdoor', 'tempat indoor (ber AC) dan outdoor, harga terjangkau 👍 …', 5, 'suasana', 'positif', 'benar', NULL, NULL, '2026-10-26 01:23:55'),
  (141, 41, 'Jelas tidak sepadan dengan harga yang mereka tetapkan', '1 bintang untuk makanan terburuk dan terkecil yang mungkin ada, dan rasanya pun tidak enak. Jelas tidak sepadan dengan harga yang mereka tetapkan. Lebih baik saya membayar 10 ribu kepada pedagang kaki lima dan memberi tip tambahan 20 ribu daripada menghabiskan uang di sini. Mengerikan. 1 bintang lagi untuk kebersihan dan suasana yang nyaman. Tapi hanya itu saja.', 2, 'harga', 'netral', 'salah', 'negatif', 'harga tidak sepadan brrti negatif lah', '2026-10-26 01:28:00'),
  (142, 42, 'sejam lebih nunggu pesanan belum datang', 'pelayanannya lama banget, sejam lebih nunggu pesanan belum datang, ojol dibelakangkan padahal lebih dulu datang dari pelanggan biasa', 3, 'pelayanan', 'netral', 'salah', 'negatif', 'sejam lebih nunggu itu termasuk negatif soalnya pelayanan lama', '2026-10-26 01:28:00'),
  (143, 43, 'ada croissant dan bomboloni juga', 'Tempatnya Nyaman polll.... Menunya lengkap, ada croissant dan bomboloni juga.. JUARA!!', 5, 'makanan_minuman', 'positif', 'salah', 'netral', 'dia cuman bilang menu tersedia doang ga bilang enak', '2026-10-26 01:28:00'),
  (144, 44, 'Pesanan hampir 2 jam belum diantar', 'Pesanan hampir 2 jam belum diantar.. Anak anak yang awalnya lapar sampai ketiduran nunggu makanan', 1, 'pelayanan', 'negatif', 'benar', NULL, NULL, '2026-10-26 01:28:00'),
  (145, 45, 'Tempatnya nyaman asik buat ngopi bareng temen temen Pelayanannya bagus', 'Tempatnya nyaman asik buat ngopi bareng temen temen Pelayanannya bagus', 5, 'suasana', 'positif', 'benar', NULL, NULL, '2026-10-26 01:28:00'),
  (146, 46, 'Nyaman dan menyenangkan juga', 'Tempat kuliner yang bagus. Makanan lezat dengan harga terjangkau. Lokasi bagus. Nyaman dan menyenangkan juga. Sangat direkomendasikan.', 4, 'suasana', 'positif', 'benar', NULL, NULL, '2026-10-26 01:28:00'),
  (147, 47, 'pilihan menu kopinya memadai', 'Harganya relatif terjangkau, pilihan menu kopinya memadai, lokasinya relatif nyaman untuk kongkow kekinian.', 4, 'makanan_minuman', 'positif', 'benar', NULL, NULL, '2026-10-26 01:28:00'),
  (148, 48, 'pelayanan sangat ramah Terimakasih buat mas rizky dan mas irfan', 'Makanannya enak, tempatnya juga nyaman, pelayanan sangat ramah Terimakasih buat mas rizky dan mas irfan', 5, 'pelayanan', 'positif', 'benar', NULL, NULL, '2026-10-26 01:28:00'),
  (149, 49, 'tempat yang paling bawah sempit dan gelap', 'Minumannya terlalu manis, tempat yang paling bawah sempit dan gelap, dan stop kontaknya kurang, jadi ngga nyaman', 2, 'suasana', 'netral', 'salah', 'negatif', 'sempit dan gelap jelas masuk negatif dong', '2026-10-26 01:28:00'),
  (150, 50, 'dan cocok buat tempat nugas', 'tempatnya bersih,enak,sejuk,teduh, dan cocok buat tempat nugas', 5, 'suasana', 'positif', 'salah', 'positif', 'cocok buat nugas masuk ke fasilitas wfc yaa, pokok kalau berkaitan tengan tugas nugas itu masuk ke fasilitas wfc', '2026-10-26 01:28:00'),
  (151, 51, 'tempatnya enak untuk nugas ataupun nongkrong', 'tempatnya enak untuk nugas ataupun nongkrong, tempat duduk cukup banyak dan area juga cukup luas. colokan cukup banyak di table pinggir makanan dan minumannya agak failed sih yaa, untuk ukuran gelas cukup besar tapi … Lainnya', 4, 'fasilitas_wfc', 'positif', 'benar', NULL, NULL, '2026-10-26 01:28:00'),
  (152, 52, 'Mie ayam jamur keasinan dan jamur bukan jamur kancing seperti difoto', 'Over all makanan oke rasanya. Koloke oke. Mie ayam jamur keasinan dan jamur bukan jamur kancing seperti difoto, melainkan jamur kuping, keasinan juga tp asinnya masih bisa ditolerir. Untuk dawet, saya tidak menulis dawet dessert di pesanan, saya pesen dawet biasa. Tapi kasir input dawet dessert dengan harga 3x lipat. Pelayan awalnya membawakan dawet biasa dan diambil lg. Saya meminta konfirmasi, saya pesan biasa. Tidakpapa sesuai yg dibawakan karena memang pesannya itu. Tp tidak ada etikat untuk mengganti nota dan mengonfirmasi sesuai pesanan, tibatiba dibawakan dawet dessertnya. Saya tidak masalah dengan nominal, namun harusnya kasir mengonfirmasi, kalaupun pelayan sudah benar membawakan yg biasa dan pelanggan tidak masalah, harusnya pihak kasir yg bertanggung jawab mengganti notanya. Mohon bisa untuk evaluasi bila ada tumpang tindih jenis menu, kasir harusnya mengonfirmasi jenis apa yg diinginkan pelanggan. Dan ini terjadi jg pada lemon tea ice yg harga 6 ribu jd 15 ribu dengan alasan sirup berbeda tanpa ada konfirmasi. Semoga lbh baik lg dan tdk bikin pelanggan jd kapok untuk dtg lg hanya karena pelayanan kasir tidak bagus, tidak ada konfirmasi, dan tidak solutif bila memang salah.', 1, 'makanan_minuman', 'negatif', 'benar', NULL, NULL, '2026-10-26 01:28:00'),
  (153, 53, 'malang sih emang keren yak Coffee shop yang udah lama ada di malang ini bagus banget dari segi rasa kopinya', 'Mmmm.malang sih emang keren yak Coffee shop yang udah lama ada di malang ini bagus banget dari segi rasa kopinya, feel ruangannya yg enak untuk ngobrol, lantai atas yang asik banget. Oiya disini ada jualan cup/tumbler nya kopi ya. Jadi bagus deh buat yg mau beli beli juga Suasana dan rasa kopinya tuh mantep sih Pelayanan yang juga ramah. Mantep dah. Lokasi coffee shop ini mih yang bikin dia menjadi diinget, di deket telkomselnya kayu tangan. Jadi kalo malem agak sepi gitu jalanannya. Kita mau duduk duduk menikmati lampu jalan kota dengan suasana yang nyaman banget Dari rasa kopi dan susunya seger banget. Bikin ga kerasa kalo kopinya mau abis😂😂 . Cocok banget dah buat nongkro rame/berdua/sendirian maen laptop.', 5, 'makanan_minuman', 'positif', 'benar', NULL, NULL, '2026-10-26 01:28:00'),
  (154, 54, 'Yang suka foto* wajib kesini deh', 'Cafe ngopi dengan desain yang nyaman , santai . Bisa ditaman ataupun di indoor . Yang suka foto* wajib kesini deh . Pelayannya juga ramah ..', 4, 'suasana', 'positif', 'benar', NULL, NULL, '2026-10-26 01:28:00'),
  (155, 55, 'suasana nyaman bgt enak buat kumpul keluarga', 'suasana nyaman bgt enak buat kumpul keluarga', 5, 'suasana', 'positif', 'benar', NULL, NULL, '2026-10-26 01:28:00'),
  (156, 56, 'Yang ga oke kang parkir', 'Minuman oke enak semua, makanan juga rasanya oke. Paling suka sama suasananya yang cozy trus disediain juga mainan-mainan macam monopolly dll. Harga standar cafe pada umumnya. Yang ga oke kang parkir, klo pake motor bayar 5k kembalian 2k. Katanya tarif emank segitu. Malang kota kang parkir. 🫡 … Lainnya', 4, 'fasilitas_wfc', 'negatif', 'benar', NULL, NULL, '2026-10-26 01:28:00'),
  (157, 57, 'Sarapan pagi di Harmoni Cafe tuh worth it banget', 'Sarapan pagi di Harmoni Cafe tuh worth it banget. Datang jam 07.00 pagi udah buka, jadi aman buat yang cari breakfast spot. Pesanan kita: es dawet klaten spesial, es kopi, gorengan campur, roti jadul yang … Lainnya', 5, 'harga', 'positif', 'benar', NULL, NULL, '2026-10-26 01:28:00'),
  (158, 58, 'Suasana biasa', 'Suasana biasa, sometimes crowded, sometimes noisy karena ada yang bikin gaduh, sometimes peaceful, sometimes annoying karena ada pasangan tak resmi yang menjadikan sebagai tempat pacaran. Tapi makanannya enak, dan pelayanannya lumayan. Lainnya', 5, 'suasana', 'netral', 'benar', NULL, NULL, '2026-10-26 01:28:00'),
  (159, 59, 'MURAAH MURAH BGT ++++ ada musholanya', 'MURAAH MURAH BGT ++++ ada musholanya', 5, 'harga', 'positif', 'benar', NULL, NULL, '2026-10-26 01:28:00'),
  (160, 60, 'baru diinfokan kalau habis sekitar 25-30 menit setelah menunggu', 'Makanannya enak, dan porsinya banyak, worth it dengan harganya. Pasta nya enak. Tpi ketika kesini kemarin ada beberapa menu yg dipesan tibatiba ternyta habis dan baru diinfokan kalau habis sekitar 25-30 menit setelah menunggu, jdi saat … Lainnya', 4, 'pelayanan', 'netral', 'salah', 'negatif', 'pelayananya kurang soalnya setelah nunggu baru diinfo jadi ga langsung', '2026-10-26 01:28:00'),
  (161, 61, 'ga pelit untuk memberikan edukasi tentang kopi', 'Kopi yg disajikan banyak sekali ragamnya dari kopi nusantara hingga kopi import dengan manual brewing khas yg ditawarkan sehingga bisa mencoba beberapa macam kopi sekaligus barista-barista nya ramah dan ga pelit untuk memberikan edukasi tentang kopi dan tempat sm pelayanan yg diberikan cozy bgt.', 5, 'makanan_minuman', 'positif', 'benar', NULL, NULL, '2026-10-26 01:31:43'),
  (162, 62, 'telor ceplok Ada pelayan yang imoet mba ayu', 'Untuk rasa menurut saya biasa aja .. Tempat bagus dan suasana yang bikin betah nongkrong Susu jahe kurang pedes Pesan ayam teriyaki bumbu meresap ke dalam daging di balur dengan wijen Dan pakai telor ceplok Nasi goreng kampung dengan ayam suwir dan telor ceplok Ada pelayan yang imoet mba ayu', 5, 'pelayanan', 'positif', 'benar', NULL, NULL, '2026-10-26 01:31:44'),
  (163, 63, 'Pengalaman berbeda ngopi di kedai kopi yg industrial di pasar tradisional', 'Pengalaman berbeda ngopi di kedai kopi yg industrial di pasar tradisional', 5, 'makanan_minuman', 'positif', 'benar', NULL, NULL, '2026-10-26 01:31:44'),
  (164, 64, 'suasana okee', 'Kalau kesini malem2, yang ga kuat dingin plis bawa jaket. Drink okee, suasana okee', 5, 'suasana', 'positif', 'benar', NULL, NULL, '2026-10-26 01:31:44'),
  (165, 65, 'kopinya rekomen dengan harga yang worth it', 'Small space, enak buat sendirian, kopinya rekomen dengan harga yang worth it', 5, 'harga', 'positif', 'benar', NULL, NULL, '2026-10-26 01:31:44'),
  (166, 66, 'sukaa 🥰 1. STAF RAMAH', 'ke sini untuk buka puasa pas Ramadan kemarin. sukaa 🥰 1. STAF RAMAH. semua pertanyaan dijawab dengan ramah dan dijelaskan dengan baik, padahal lagi hectic menuju buka puasa. 2. PARKIR AMAN buat motor maupun mobil, lega parkirnya.. 3. FOOD OKE. rasanya enak, sausnya ngga pelit, dan porsinya manteb. kenyang pokoknyaa.. harga pantes banget lah ngga rugi. porsi minuman juga oke (gelas rata2 gede).. 4. SUASANA enak dan ngga bising sama kendaraan lalu lalang. meja kursi & colokan banyak, WIFI kenceng. kemarin ke sana bareng keluarga, dan ada juga kakak2 yg lagi nugas. kalau mau nyore bisa di outdoor belakang yaa, adem dan suasana senjanya dapet banget. 5. TOILET bersih dan wangi rempah. yang mau sholat dont worry masjid deket banget jalan kaki bisa. next mau nunggu bocil sekolah sambil buka laptop deh (sekolah bocil di Sutoyo, deket banget) ✨', 5, 'pelayanan', 'positif', 'benar', NULL, NULL, '2026-10-26 01:31:44'),
  (167, 67, 'Tempatnya dan pelayanannya mengesankan', 'Tempatnya dan pelayanannya mengesankan, cocok dijadikan tempat nongkrong dengan vibes santaiMakanan:… Lainnya', 5, 'suasana', 'positif', 'benar', NULL, NULL, '2026-10-26 01:31:44'),
  (168, 68, 'tersedia colokan juga bagi yang mau mengerjakan tugas', 'Lokasi ditengah kota dekat dengan whiz prime hotel. Suasana nyaman , ada outdoor ada indoornya juga. Cukup luas untuk area outdoornya. tersedia colokan juga bagi yang mau mengerjakan tugas. Rasa dessertnya 4/5. Harga standart. Lainnya', 5, 'fasilitas_wfc', 'positif', 'benar', NULL, NULL, '2026-10-26 01:31:44'),
  (169, 69, 'sorry to say untuk mbk kasir nya ga ramah banget perlu di training ulang ya', 'sorry to say untuk mbk kasir nya ga ramah banget perlu di training ulang ya? sama karyawan yg lain jutek bgt plis sempet nanya nanya seputar menu yg mirip sm ice tea itu apa mbk kasir nya blg '' … Lainnya', 1, 'pelayanan', 'negatif', 'benar', NULL, NULL, '2026-10-26 01:31:44'),
  (170, 70, 'parkiran juga enak', 'Tempatnya enak buat belajar sama rapat, AC nya dingin di dalam ruangan, musiknya enak gak terlalu kencang, tempatnya estetik sama luas banyak tempat duduk & parkiran juga enak, pengunjung yang nama rachel cantik gila parahhhh', 5, 'makanan_minuman', 'positif', 'benar', NULL, NULL, '2026-10-26 01:31:44'),
  (171, 71, 'Rumah kuno yang dijadikan tempat ini menambah aksen menarik bagi pengunjung', 'Coffee shop yang menyajikan kopi beraneka rasa seperti vanilla latte dan lain-lain. Makanan ringan juga disediakan. Rumah kuno yang dijadikan tempat ini menambah aksen menarik bagi pengunjung.', 5, 'suasana', 'positif', 'benar', NULL, NULL, '2026-10-26 01:31:44'),
  (172, 72, 'pilihan menu yang beragam', 'Tempat nyaman dan cocok buat rehat setelah seharian capek sama kerjaan, pilihan menu yang beragam dan karyawan yang ramah bikin betah lama lama di situ🥰 …', 5, 'makanan_minuman', 'positif', 'benar', NULL, NULL, '2026-10-26 01:31:44'),
  (173, 73, 'semoga kedepannya bisa lebih banyak colokan yang bagus', 'tempatnya bagus, tapi untuk colokan di rooftop tidak bisa untuk mengecas, semoga kedepannya bisa lebih banyak colokan yang bagus', 5, 'fasilitas_wfc', 'positif', 'salah', 'negatif', 'dia bilang kalau di rooftop gabisa buat ngecas, yg ditulis ini harapan kedepanya', '2026-10-26 01:31:44'),
  (174, 74, 'Tempat sejuk dan teduh karena banyak tanaman hijau', 'Tempat ngopi yang ada di Malang. Suasana sedikit berbeda karena bisa bersantai sambil melihat kereta lewat (kalo lewat). Tempat sejuk dan teduh karena banyak tanaman hijau. Makanan minuman juga enak dan harga bersahabat.', 5, 'suasana', 'positif', 'benar', NULL, NULL, '2026-10-26 01:31:44'),
  (175, 75, 'Lafayette ini ada 3 lantai', 'Lafayette ini ada 3 lantai, jadi bisa leluasa pilih tempat. Makanannya ada yang bisa langsung dilihat di etalase dan ada juga yang harus lewat buku menu. Dari beberapa menu yang dipesen, kira-kira review-nya gini: Zuppa soup-nya enak, apel … Lainnya', 4, 'kebersihan', 'netral', 'benar', NULL, NULL, '2026-10-26 01:31:44'),
  (176, 76, 'banyak sudut untuk spot foto', 'Pertama kali makan disini, ruangannya enak untuk kumpul keluarga, pelayanannya ramah dan baik, banyak sudut untuk spot foto, dan sangat happy dengan harmony cafe dengan karyawan disabilitasnya yang sangat baik.. Sukses selalu untuk harmony cafe.. Lainnya', 5, 'suasana', 'positif', 'benar', NULL, NULL, '2026-10-26 01:31:44'),
  (177, 77, 'Portal Coffee Malang ini jadi satu lokasi dengan The Roots Barbershop Malang', 'Sebelumnya, Portal Coffee Malang ini jadi satu lokasi dengan The Roots Barbershop Malang. Tapi kini keduanya pindah ke lokasi terpisah di dekat tempat lama. Yang paling favorit di sini tentu olahan kopinya. Saat sore hari, pengunjung juga bisa melihat sendiri proses penyangraian kopi. Ada berbagai jenis biji kopi robusta dan arabika yang ditawarkan. Mulai produk lokal Malang maupun beberapa daerah lain. Olahan yang ciamik ada kopi susu gula aren, kopi tubruk, V60, afogato, dan lain-lain. Bagi yang tidak suka kopi, ada pilihan minuman tradisional seperti wedang uwuh, beras kencur dan kunyit asam. Kualitas dan rasanya patut diperhitungkan.', 5, 'makanan_minuman', 'positif', 'salah', NULL, 'lebih ke suasana si', '2026-10-26 01:31:44'),
  (178, 78, 'Pelayanan ke driver online sangat buruk', 'Pelayanan ke driver online sangat buruk', 1, 'pelayanan', 'negatif', 'benar', NULL, NULL, '2026-10-26 01:31:44'),
  (179, 79, 'tempatnya memang indah', 'Secara estetika, tempatnya memang indah, tidak diragukan lagi. Tapi sayang sekali, pelayanannya sangat lambat. Padahal, kami adalah satu-satunya pelanggan saat itu (6 orang). Untuk restoran ternama, ini sungguh mengecewakan. Jika Anda … Lainnya', 2, 'suasana', 'positif', 'benar', NULL, NULL, '2026-10-26 01:31:44'),
  (180, 80, 'menu ini wajib banget pesen cookies and cream', 'Menu ini penyelamat banget buat yang lagi gak pengen minuman tapi butuh yang manis-manis seger pas sore hari. Buat yang cari opsi non-kopi di Studio 24, menu ini wajib banget pesen cookies and cream! Lainnya', 5, 'makanan_minuman', 'positif', 'benar', NULL, NULL, '2026-10-26 01:31:44'),
  (181, 81, 'co pada umumnya: interior', 'Seperti J.co pada umumnya: interior, menu, karyawannya. No complains.', 5, 'suasana', 'positif', 'benar', NULL, NULL, '2026-10-26 01:38:21'),
  (182, 82, 'WiFi juga cukup kencang di 60mbps (update: per Februari 2026', 'Salah satu tempat yang asik buat nongkrong. Minuman dan jajanannya variatif, rasanya juga enak dan menyenangkan. Dipakai untuk kerja ataupun nugas juga cocok, colokan lumayan banyak tersedia, WiFi juga cukup kencang di 60mbps (update: per Februari 2026, WiFi nya sudah diupgrade dengan kecepatan hampir 200 Mbps di jam sibuk). Paling syahdu nongkrong di sini sewaktu senja, dapet banget atmosfernya. Last speed test: Down 184,00 Mbps / Up 147,34 Mbps (25 Februari 2026)', 5, 'fasilitas_wfc', 'positif', 'benar', NULL, NULL, '2026-10-26 01:38:21'),
  (183, 83, 'donatnya enak empuk', 'tempatnya cukup nyaman, ada outdoornya, kopi standar with reasonable price, donatnya enak empuk, plenty of parking spaces', 5, 'makanan_minuman', 'positif', 'benar', NULL, NULL, '2026-10-26 01:38:21'),
  (184, 84, 'Kayaknya kurang cocok untuk yg pgn kerja laptopan', 'Tempatnya bagus dan luas, banyak pilihan, bisa di dalam ruangan yang bawah atau atas, bisa di luar ruangan sambil lihat jalan. Kecuali pagi, di sini sering penuh dan ramai. Kayaknya kurang cocok untuk yg pgn kerja laptopan. Lainnya', 5, 'fasilitas_wfc', 'positif', 'salah', 'negatif', 'kurang cocok kalo pgn kerja laptopan, brrti wfcnya negatif dong', '2026-10-26 01:38:21'),
  (185, 85, 'Hazelnut lattenya enak', 'Pertama kali ngopi disini sama temen" kuliah. Enak tempatnya luas banget, bisa dapet tempat duduk meskipun rame parah. Sayangnya toilet cuma ada 1 cowok 1 cewek. Jadi kalo mau ke toilet harus antri dulu lumayan lama. Hazelnut lattenya enak, meskipun tadi pesan panas, tapi datangnya udah hangat, cenderung suhu biasa.. Lainnya', 5, 'makanan_minuman', 'positif', 'benar', NULL, NULL, '2026-10-26 01:38:21'),
  (186, 86, 'Pelayanan ambek menu e muwasok 👍', 'Pelayanan ambek menu e muwasok 👍', 5, 'makanan_minuman', 'positif', 'benar', NULL, NULL, '2026-10-26 01:38:21'),
  (187, 87, 'Tempat favoritkuuu buat skripsiannn❤️', 'Tempat favoritkuuu buat skripsiannn❤️. Tempatnya super nyaman, banyak colokan, wifinya lancar, dan ambience nya tenang karena lebih banyak yg wfc daripada yang nongkrong. Menu minuman dan makanannya juga ramah di kantong mahasiswa. Btw ini tempat favoritku juga sama teman-temanku xixixi. Kasir dan baristanya ramah, komunikatif, dan helpful banget kalau ditanya-tanya soal menu. Cocok buat yang suka eksplor menu-menu kopi disini. Sukses selalu buat calfff, semoga buka terus sampai hari kiamat 💻☕', 5, 'suasana', 'positif', 'benar', NULL, 'skripsian termasuk ke fasiias wfc jugaa', '2026-10-26 01:38:21'),
  (188, 88, 'harga 29.000 isi cuman air', 'Es Sarang Burung walet terburuk di dunia, harga 29.000 isi cuman air, Sirup, jely cuman berapa Potong, di Komplain baru di kasih tambahan isi. sekelas Harmoni Ikan Gurame rasa tanah, sapo Tahu rasa Plain. Lainnya', 1, 'harga', 'negatif', 'benar', NULL, NULL, '2026-10-26 01:38:21'),
  (189, 89, 'karena sejujurnya karpet mushollanya sangat bau apek', 'Dear Aadk, Tempat dan suasananya sudah baik, tapi saya sebagai pelanggan punya dua masukan yang moga2 ditindaklanjuti. Pertama, tolong karpet mushollanya sering2 di laundry, minimal 1 bulan 2 kali, karena sejujurnya karpet mushollanya sangat bau apek dan bau kaki. Itu berapa tahun udah ngga pernah dicuci? Mungkin sesekali, lantai mushollanya bisa dipel pakai pewangi. Ini sederhana sekali, tapi sangat membantu meningkatkan kenyamanan. Kedua, pihak parkirnya jangan cuma minta uang parkir lalu pas keluar tidak dibantuin apa-apa. Minimal bantuin untuk nyebrang karena sulit untuk menyebrang arah tanpa bantuan dari pihak parkir. Semoga ditindaklanjuti ya, karena seringkali yang bikin orang nyaman datang ke cafe bukan cuma karena makanannya, tapi hal-hal sederhana kaya gini tolong diperhatikan. Trimss!', 5, 'kebersihan', 'negatif', 'benar', NULL, NULL, '2026-10-26 01:38:21'),
  (190, 90, 'makanannya luamayn enak harganya ya lumayan 😂 …', 'makanannya luamayn enak harganya ya lumayan 😂 …', 4, 'makanan_minuman', 'positif', 'salah', 'netral', 'dia bilang makananya lumayan hargaanya juga, termasuk netral aja deh klo bilang harganya lumayan tu', '2026-10-26 01:38:21'),
  (191, 91, 'Cocok untuk lingkungan kerja lepas yang kolaboratif dan untuk membangun jaringan', 'Kedai kopi yang layak dan juga ruang kerja umum. Cocok untuk lingkungan kerja lepas yang kolaboratif dan untuk membangun jaringan. Lokasinya unik, berada di kawasan komersial yang ramai di pusat kota Malang, menargetkan pekerja kantoran dan … Lainnya', 5, 'fasilitas_wfc', 'positif', 'benar', NULL, NULL, '2026-10-26 01:38:21'),
  (192, 92, 'Herga menu lumayan murah meskipun menu yg tersedia belum begitu bervariasim enak buat nugas', 'Suka banget dg view cafenya. Lokasi persawahan yg kalo lagi menghijau jadi instagrammable banget buat foto-foro. Herga menu lumayan murah meskipun menu yg tersedia belum begitu bervariasim enak buat nugas, ato sekedar cangkruan ngumpul2. … Lainnya', 5, 'makanan_minuman', 'netral', 'salah', 'positif', 'dia typo bilang harga jadi herga', '2026-10-26 01:38:21'),
  (193, 93, 'Harga juga medium', 'Pelayanan sih ok banget ya, sudah mirip restoran besar, sangat ramah dan friendly ke tamu yang berkunjung, memberi rekomendasi makanan yang enak. Harga juga medium, tidak mahal. Untuk makanan berat rasanya sih secara umum sudah ok, tapi … Lainnya', 5, 'harga', 'positif', 'benar', NULL, NULL, '2026-10-26 01:38:21'),
  (194, 94, 'colokan cukup banyak di table pinggir makanan dan minumannya agak failed sih yaa', 'tempatnya enak untuk nugas ataupun nongkrong, tempat duduk cukup banyak dan area juga cukup luas. colokan cukup banyak di table pinggir makanan dan minumannya agak failed sih yaa, untuk ukuran gelas cukup besar tapi … Lainnya', 4, 'makanan_minuman', 'netral', 'salah', 'positif', 'dia bilang banyak colokan tapi minumanya failed alias ga enak brrti', '2026-10-26 01:38:21'),
  (195, 95, 'wort it 👍🏻 Cocok buat nongkrong santai', 'Nongkrong di Djavu Caffe Malang emang nyaman ☕✨ Tempatnya cozy dan estetik, vibes-nya chill banget. Kopinya enak, makanannya juga enak dan wort it 👍🏻 Cocok buat nongkrong santai, ngobrol lama, atau sekadar ngopi cantik. Pelayanannya ramah, tempatnya bersih, dan bikin betah. Recommended buat cafe hopping di Malang 🤍📸', 5, 'suasana', 'positif', 'benar', NULL, NULL, '2026-10-26 01:38:21'),
  (196, 96, 'untuk harga nya juga affordable', 'Spot kopitiam di malang yg bisa dikunjungi dari pagi hari. Lokasi nya deket stasiun malang jadi kalo lagi liburan naik kereta bisa langsung mampir kesini. Tempatnya memang ga terlalu besar lumayan saja. Tapi tempat duduk nya lumayan banyak di dalem dan outdoor sebagian. Disini tersedia berbagai minuman dari coffe maupun non coffe. Makanan dan snack nya lumayan lengkap dan untuk harga nya juga affordable.', 5, 'harga', 'positif', 'benar', NULL, NULL, '2026-10-26 01:38:21'),
  (197, 97, 'harga yang di tawarkan menurut saya sama seperti cafe pada umumnya', 'Untuk tempat cozy, harga yang di tawarkan menurut saya sama seperti cafe pada umumnya. Untuk kantong mahasiswa sedikit lebih mahal menurut saya. Tapi sesuai dengan kualitas lah 😎 …', 4, 'harga', 'netral', 'benar', NULL, NULL, '2026-10-26 01:38:21'),
  (198, 98, 'Dtg pas malming rame pilihan tempat duduk bnyk ada yg diluar d dlm', 'Dtg pas malming rame pilihan tempat duduk bnyk ada yg diluar d dlm. Wifi lumayan. Katsu kare nya enak. Spaghettinya b aja', 5, 'suasana', 'positif', 'benar', NULL, NULL, '2026-10-26 01:38:21'),
  (199, 99, 'Service nya jelek banget dan lama', 'Service nya jelek banget dan lama. Bagian kasir dan dapur saling salah-salahan. Indomie Telor butuh 40menit buat sampai di meja. Ga rekomendasi banget. Lainnya', 1, 'pelayanan', 'negatif', 'benar', NULL, NULL, '2026-10-26 01:38:21'),
  (200, 100, 'Kalo punya karyawan seperti itu udah saya buang sangat tidak menghargai customer yang sudah berlangganan bukti uang masih saya simpan sampai detik ini', 'Udah beberapa kali nongkrong di sini yang saya kecewa saya pesan salah satu minuman terus ada yang kembalian uang yang saya terima rusak sobek. Kalo punya karyawan seperti itu udah saya buang sangat tidak menghargai customer yang sudah berlangganan bukti uang masih saya simpan sampai detik ini', 1, 'pelayanan', 'negatif', 'benar', NULL, NULL, '2026-10-26 01:38:21');
