INSERT INTO validasi_v5 ("id", "urutan", "sub_kalimat", "teks_ulasan", "rating", "aspek", "sentimen", "status", "sentimen_koreksi", "catatan", "diperiksa_pada") VALUES
  (1, 1, 'plis diperbaiki yaa sayang bgt tempatnya udh oke', 'kesini gara2 penasaran ajaa karena bangunan nya yg okee new konsep buat di malang. taaapiii 1. pilih smooking area yg ber ac bener2 bau rokok padahal ada 2 exhaust tapi ttp ga mempan 2. self service yang kita gatau kapan makanan / minuman yg udh dipesan udh selesai? aga gajelas aja kalo self service tp kaya gt konsep nya 3. beli 3 minuman tapi nunggu nya hampir 30menit sendiri. tentu sajaa staff nya cuma sendiri dan jd kasir jd ya lama lah 4. beberapa publik area kotor kaca2nya kotor emmm sorry for bad reviews.. plis diperbaiki yaa sayang bgt tempatnya udh oke', 3, 'suasana', 'positif', 'salah', NULL, 'plss diperbaiki ya itu brrti antara pelayanan sama suasananya kurang', '2026-10-26 03:42:18'),
  (2, 2, 'Salah satu tempat ngopi favorite', 'Salah satu tempat ngopi favorite, pilihan menu kopi banyak, rasa enak, tempat juga enak, yang agak kurang cuma', 5, 'suasana', 'positif', 'benar', NULL, NULL, '2026-10-26 03:42:18'),
  (3, 3, 'Staff nampaknya tdk ada yg senyum', 'Porsi dikit untuk harga standar cafe. Ga dikasih tisu kecuali minta. Agak sempit tempat duduknya. Staff nampaknya tdk ada yg senyum. Oiya waktu ksana ada yg merayakan small surprise birthday party, staff bisa diajak kerjasama utk nyalain lagu by request. Lumayan.', 4, 'pelayanan', 'netral', 'benar', 'netral', 'staff tidak ada yg senyum itu termasuknya ke negatif', '2026-10-26 03:42:18'),
  (4, 4, 'Harga dari menunya lumayan terjangkau', 'Salah satu cafe yang sangat nyaman dan tenang untuk nugas atau sekedar nongkrong bersama kawan-kawan. Harga dari menunya lumayan terjangkau, sesuai untuk ukuran kantong mahasiswa.', 4, 'harga', 'positif', 'benar', NULL, NULL, '2026-10-26 03:42:18'),
  (5, 5, 'makan minumnya juga affordable buat mahasiswa', 'tempatnya luas dan ga sumpek, banyak colokan juga tpi klo kalian mau wfc mending bawa kabel roll sih. makan minumnya juga affordable buat mahasiswa. tpi thai teanya kebanyakan air. jdi rasanya ngambang?? and unfortunately toiletnya gaada tisue di dalem biliknya, even trash bin pun gaada. memang ada sih tisue di deket wastafel tpi itu kan buat lap cuci tangan ya😅 ini agak sakral klo buat cewe krn klo habis buang air hrusnya ada tisue..', 4, 'harga', 'positif', 'benar', NULL, NULL, '2026-10-26 03:42:18'),
  (6, 6, 'Coffee shop andalan kalau butuh kopi pagi-pagi', 'Coffee shop andalan kalau butuh kopi pagi-pagi', 5, 'makanan_minuman', 'positif', 'benar', NULL, NULL, '2026-10-26 03:42:18'),
  (7, 7, 'Berasa minum kopi jadul', 'Klo di jakarta ada es kopi tak kie, di malang ada toko kopi kongca. Berasa minum kopi jadul', 5, 'makanan_minuman', 'positif', 'benar', NULL, NULL, '2026-10-26 03:42:18'),
  (8, 8, 'Area outdoor-nya ada sekitar 4 meja dengan beberapa tempat duduk', 'Fore coffee ini beda dengan kedai kopi sejenis ya. Secara konsep dan menu lebih premium. Layak berkompetisi dengan Starbuck. Area outdoor-nya ada sekitar 4 meja dengan beberapa tempat duduk, nyaman untuk menikmati udara sejuk Kota Malang. Hanya saja yang lumayan mengganggu adalah suara bising knalpot dari kendaraan yang berlalu lalang. Area indoor-nya bagus dengan penataan yang estetik dan sejuk karena ruangannya ber-AC. Untuk bekerja kita bisa menggunakan area indoor karena lebih tenang tidak bising dan juga cukup nyaman. Saya sarankan memakai jaket supaya badan tidak terlalu kedinginan. Fore VS Starbuck : Suasana di sore itu lebih ceria dan tidak terlalu serius. Cocok untuk santai dan juga bekerja. Sedangkan Starbuck suasana itu lebih formal dan juga kalem. Cocok banget untuk bekerja dan juga santai sepulang dari kantor. Untuk harga makanan dan minuman tentu sedikit lebih mahal Starbuck ya. Fore ini posisi harganya berada di tengah, antara Kopi Kenangan dan Starbuck. Kalau untuk gengsi memang Starbucks lebih unggul. Saya sendiri kalau untuk kerja serius lebih memilih Starbucks sedangkan kalau untuk kerja santai saya akan mempertimbangkan di fore. Sukses selalu untuk FORE.', 5, 'suasana', 'netral', 'benar', NULL, NULL, '2026-10-26 03:42:18'),
  (9, 9, 'Fettuccini-nya enak', 'Hanya harga ''murah'' lain yang dipatok untuk nonkrong yang tidak menyediakan minuman panas. Fettuccini-nya enak. Tapi pisang gorengnya keras dan sulit dikunyah. Dan mwnu lainnya hanya kentang goreng dari makanan beku.', 3, 'makanan_minuman', 'positif', 'benar', NULL, NULL, '2026-10-26 03:42:18'),
  (10, 10, 'tapi toilet cuma 1.', 'Rasa enak, pelayanan kakak2 nya ramah, ramai mulai maghrib - malam. Ada mushola di atas, tapi toilet cuma 1.', 5, 'fasilitas_wfc', 'positif', 'ragu', NULL, 'toilet cuma 1 itu termasuk positif apa negatif ya? kan jadinya harus antri ke toilet', '2026-10-26 03:42:18'),
  (11, 11, 'Tempat nyaman makanan enak Hrg terjangkau', 'Tempat nyaman makanan enak Hrg terjangkau', 5, 'makanan_minuman', 'positif', 'benar', NULL, NULL, '2026-10-26 03:42:18'),
  (12, 12, 'Tempat yang nyaman untuk santai', 'Tempat yang nyaman untuk santai. Masuk di dalam perumahan. Hidden Gem. Makanan aman dan enak, service friendly, kopi kerinci yang dibikin hot americano enak, mocktail enak. Suasana di dalam enak dan nyaman. Homy banget. Mantap. Di malang … Lainnya', 5, 'suasana', 'positif', 'benar', NULL, NULL, '2026-10-26 03:42:18'),
  (13, 13, 'soalnya tmpatnya nyaman', 'Nokoa seperti rmh sendiri, soalnya tmpatnya nyaman.', 5, 'suasana', 'positif', 'benar', NULL, NULL, '2026-10-26 03:42:18'),
  (14, 14, 'dan semu outdoornya luas tp full asep rokok vape + panas Lainnya', 'Buat makanan sm minumannya overall ok, waktu itu aku pesen pasta sm chicken wings, minumannya lupa apa, cmn untuk yg cari tempat nongki/nugas yg adem, menurutku kurang, krn space indoornya kecil, dan semu outdoornya luas tp full asep rokok vape + panas Lainnya', 3, 'suasana', 'netral', 'salah', 'negatif', 'full asap rokok vape + panas itu brrti negatif', '2026-10-26 03:42:18'),
  (15, 15, 'untuk rasa makananya menurut aku cocok sih buat lidah ku', 'Well kemarin baru pertama kali kesini. Untuk tempatnya cozy dan homey banget sih dan untuk rasa makananya menurut aku cocok sih buat lidah ku dan enak. Menurutku disini cocok banget buat yang butuh me time karna nyaman banget tempatnya berasa dirumah sendiri loh.', 5, 'makanan_minuman', 'positif', 'benar', NULL, NULL, '2026-10-26 03:42:18'),
  (16, 16, 'seperti biasa mencari inspirasi di tempat tongkrongan sambil nyeruput Kopi 😁 nyoba ngopi di Lima sebelas coffee di daerah stasiun', 'Sabtu lalu saya datang kesini,, seperti biasa mencari inspirasi di tempat tongkrongan sambil nyeruput Kopi 😁 nyoba ngopi di Lima sebelas coffee di daerah stasiun..liat depannya sih kayak cafe kecil, parkirannya juga terbatas pas masuk … Lainnya', 4, 'makanan_minuman', 'netral', 'benar', NULL, NULL, '2026-10-26 03:42:18'),
  (17, 17, 'banyak pilihan aneka menu makanan', 'Ini tempat nongkrong ngobrol dan makan salah satu yg fav gue dan keluarga ,rasanya Mak nyus harga menu yg terjangkau dan banyak pilihan aneka menu makanan dan minuman ,camilan dll ,tempatnya asik rekomended utk keluarga atopun kantor utk metting dll....Deket dengan pusat belanja MOG dll pusat kota ,cobain ya mampir pasti suka', 5, 'makanan_minuman', 'netral', 'benar', NULL, NULL, '2026-10-26 03:42:18'),
  (18, 18, 'apalagi saat ditanya password wifi', 'Tempatnya nyaman dan bersih, cuma pegawainya kurang senyum, apalagi saat ditanya password wifi', 3, 'fasilitas_wfc', 'netral', 'salah', 'negatif', 'pelayananya kurang soalnya apalagi saat ditanya password wifi, brrti kurang', '2026-10-26 03:42:18'),
  (19, 19, 'worthy buat dicoba karena makanan', 'sudah langganan di sini belasan tahun. harganya dari dulu gak begitu beda jauh, worthy buat dicoba karena makanan dan minumannya enak-enak. favorit saya sih pasta chicken kare. kalau kopinya gak usah diragukan lagi rasanya. minusnya di sini tempatnya yg emang sempit. kalau udah mulai jam makan siang atau malam ya siap-siap masuk waiting list. parkirnya gratis tapi cuma sedikit, kurang recommend kalau bawa mobil. semoga cafe lai-lai buka cabang baru yang tempatnya lebih nyaman. hehe.', 5, 'makanan_minuman', 'positif', 'benar', NULL, NULL, '2026-10-26 03:42:18'),
  (20, 20, 'harga upper class', 'Lokasi strategis, sempit, panas banget AC gak dingin, harga upper class, konsep cafe unfinished building, kopinya B aja, Juara umumnya Browniesnya .. TOP bgt', 3, 'harga', 'netral', 'salah', 'negatif', 'harga upper class brrti buat kalangan atas, masuk ke negatif aja', '2026-10-26 03:42:18'),
  (21, 21, 'tempat berada di tengah kota', 'Tempat yang sangat rekomen, nyaman, pelayanan mantap. Cocok untuk bersantai dan tempat berada di tengah kota', 5, 'suasana', 'netral', 'benar', NULL, NULL, '2026-10-26 03:54:04'),
  (22, 22, 'Tempat duduknya nyaman" aja', 'Lumayan mahal buat tempat nongkrong mahasiswa. Terus kasihan sama kakek nenek yang ngelola tempat itu. Seharusnya kakek nenek sudah beristirahat di rumah saja. Tempat duduknya nyaman" aja', 3, 'suasana', 'positif', 'benar', NULL, NULL, '2026-10-26 03:54:04'),
  (23, 23, 'agak terlalu manis utk ukuran saya', 'Kesini jam makan siang pas tanggal 26 Desember. Lumayan crowded, mungkin krn suasana liburan. Bagian belakang open space, tp agak panas. Bagian depan lebih nyaman, ada juga yg pake AC. Cuman nyobain cold white, agak terlalu manis utk ukuran saya. Makanan dan minuman bervariasi, next time coba lagi menu lain.', 4, 'makanan_minuman', 'netral', 'benar', NULL, NULL, '2026-10-26 03:54:04'),
  (24, 24, 'Suasana tempat enk jg nyaman', 'Suasana tempat enk jg nyaman..menu yg d saji kn recomended..klo pd wkt ttt terkadang butuh reservasi terlebih dahulu.Karena d khawatir kn tdk dpt meja..misal wkt puasa ramadhan..', 5, 'suasana', 'positif', 'benar', NULL, NULL, '2026-10-26 03:54:04'),
  (25, 25, 'makanan oke lahh', 'Enaknya ngopi disini pas malem, makanan oke lahh.. Worth it', 5, 'makanan_minuman', 'positif', 'benar', NULL, NULL, '2026-10-26 03:54:04'),
  (26, 26, 'Menu yang wajib dicoba dari seorang penikmat kopi amatir - Arunika ✨✨ - Matcha ganda atau cokelat … Lainnya', 'Menu yang wajib dicoba dari seorang penikmat kopi amatir - Arunika ✨✨ - Matcha ganda atau cokelat … Lainnya', 5, 'makanan_minuman', 'positif', 'benar', NULL, NULL, '2026-10-26 03:54:04'),
  (27, 27, 'cocok sekali untuk tempat kumpul bersama keluarga dan teman', 'Tempatnya nyaman, adem, bersih, dan instgramable. Suasananya juga mewah dan tenang. Untuk rasa makanan dan minumannya enak, cocok sekali untuk tempat kumpul bersama keluarga dan teman. Salah satu rekomendasi kafe ternyaman kalo ke Malang sih.. Lainnya', 4, 'suasana', 'netral', 'salah', 'positif', 'suasananya termasuknya positif dong klo cocok sekali untuk tempat kumpul bersama keluarga dan teman', '2026-10-26 03:54:04'),
  (28, 28, 'Pesannya harus satu2. Jadi kalo ada temen yg nyusul tetep bayar sendiri2 Lainnya', 'Kurang pas untuk temu janji disini untuk pekerjaan dll. Pesannya harus satu2. Jadi kalo ada temen yg nyusul tetep bayar sendiri2 Lainnya', 4, 'harga', 'netral', 'benar', NULL, NULL, '2026-10-26 03:54:04'),
  (29, 29, 'ambience untuk kerja', 'Salah satu hidden gem cafe bersejarah di Malang yang nyaman banget buat WFC (Work From Cafe) atau WFA. Suasananya tenang, adem, dan bikin fokus kerja atau nugas jadi maksimal. Fasilitas pendukungnya juga oke. Sayangnya untuk menu kopi di sini kurang variatif, pilihan jenis minumannya cenderung standar dan terbatas. Tapi kalau cari kenyamanan tempat dan ambience untuk kerja, kafe ini sangat direkomendasikan!', 4, 'suasana', 'netral', 'benar', NULL, NULL, '2026-10-26 03:54:04'),
  (30, 30, 'Sekalian bekerja', 'Enak buat nongky sore. Sekalian bekerja. Bersebrangan dengan bakso presiden. Bisa lihat KA Lewat', 4, 'fasilitas_wfc', 'netral', 'benar', NULL, NULL, '2026-10-26 03:54:04'),
  (31, 31, 'luas dsb', 'wifi okelah, tapi ga berharap lebih, disini enak kang parkir nya baik ramah, lembut gituu, tempat luas, kamar mandi okee bngt ada sabun, luas dsb, wifi nya jelek sih, terus pelayanan juga oke, pas mau tutup diingetin baik", pemuda pemuda disini yg ngurus, tempat rapat oke', 4, 'suasana', 'positif', 'benar', NULL, NULL, '2026-10-26 03:54:04'),
  (32, 32, 'minuman worth to buy', 'saya kira Roketto ini kafe, ternyata bengkel las-las an, makanan dan minuman worth to buy, cuman attitude pegawainya 0 besar, senin 8 april tepat jam 23.59 saat tutup pegawainya pada banting banting kursi buat ngusir customer, harusnya bisa … Lainnya', 1, 'makanan_minuman', 'positif', 'benar', NULL, NULL, '2026-10-26 03:54:04'),
  (33, 33, 'Space tempat banyak', 'Tempat nongkrong baru. Makanan enak. Minuman (coklat) selalu favoritku.... Space tempat banyak, tp full2 trus....', 5, 'suasana', 'positif', 'benar', NULL, NULL, '2026-10-26 03:54:04'),
  (34, 34, 'Siapa pun di Malang yang mencari kopi berkualitas tinggi dalam suasana santai dengan orang-orang yang sangat ramah', 'Sebenarnya kami ingin menyewa skuter dan menanyakan arah ke sana. Pemiliknya sangat baik dan langsung mencoba mengatur penyewaan skuter untuk kami melalui telepon, karena semua tempat penyewaan sudah tutup. Akhirnya kami mampir untuk minum kopi, dan itu adalah hal terbaik yang bisa kami lakukan. Kopinya disiapkan dengan sempurna (disajikan dengan tangan, V60) dan rasanya fantastis. Mereka menawarkan berbagai biji kopi dan tingkat sangrai yang bersumber langsung dari wilayah tersebut. Siapa pun di Malang yang mencari kopi berkualitas tinggi dalam suasana santai dengan orang-orang yang sangat ramah, pasti harus pergi ke sana. Jika kami kembali ke Malang lagi, kami pasti akan kembali.', 5, 'makanan_minuman', 'positif', 'benar', NULL, NULL, '2026-10-26 03:54:04'),
  (35, 35, 'Literally tenang bgt kayak di perpus (well', 'Di mana lagi ya nyari kafe yang suasananya gak bising kayak di sini. Literally tenang bgt kayak di perpus (well, live up to the name I guess), no music, no bising walaupun kafenya pinggir jalan. Sampe pas mesen di kasir jadi ikut melanin suara karena takut ganggu. Tapi, ini kafe tipe aku bgt rillll. Sayang jauh dari rumah. Kalo deket pasti aku samperin tiap hari hehe. Buat buku-bukunya koleksinya lengkap sih meskipun gak yang banyakkk bgt dan update bgt, tapi tetep kekinian. Bukunya ada novel, self improvement, bisnis, ensiklopedia, etc banyaklah pokoknya. Kebanyakan buku bahasa indonesia sih, kalo yang bahasa inggris kayaknya ada di deket kasir itu, cuma aku belum liat. Terus buat makanan sejujurnya agak pricey buat kantong mahasiswa kyk aku tapi worth it kok soalnya makanannya enak-enak. Kopinya juga enakkk. Cuma kalo mau makan di indoor harus segera dihabiskan kalo gak mau makanannya dingin. Soalnya AC nya kencenggg bgt. Tambahan lagi, salut bgt toiletnya bersih dan isinya lengkappp. Ada sabun, sabun cuci muka (cewe/cowo), parfum, kipas angin mini, sampe menstrual pads buat cewe juga disediain loh. Servisnya manteb bgt pokoknya👍👍', 5, 'suasana', 'positif', 'salah', NULL, 'kayak di perpus termasuk ke fasilias wfc', '2026-10-26 03:54:04'),
  (36, 36, 'minuman nya juga worth it', 'SERU BANGETTT, anjingnya lucuu semuaaa, staff nya juga ramah bangett friendlyy,, makanan dan minuman nya juga worth it,, over all bintang 5 dehh pokonyaa', 5, 'makanan_minuman', 'positif', 'benar', NULL, NULL, '2026-10-26 03:54:04'),
  (37, 37, 'Stafnya sangat ramah dan bersahabat', 'Saya sangat menyukai makanannya, melebihi harganya. Stafnya sangat ramah dan bersahabat.', 5, 'pelayanan', 'positif', 'benar', NULL, NULL, '2026-10-26 03:54:04'),
  (38, 38, 'nunggu 1 jam pesanan tak kunjung tadang 😠😵😱 …', 'Pelayanannya lama banget, nunggu 1 jam pesanan tak kunjung tadang 😠😵😱 …', 1, 'pelayanan', 'negatif', 'benar', NULL, NULL, '2026-10-26 03:54:04'),
  (39, 39, 'Pelayanannya sangat ramah dan pesanan makanannya cepat', 'Pelayanannya sangat ramah dan pesanan makanannya cepat dan tidak perlu menunggu lama meskipun banyak antrian', 5, 'pelayanan', 'positif', 'benar', NULL, NULL, '2026-10-26 03:54:04'),
  (40, 40, 'Makanan murah banget', 'spot buat belajar yg enak banget. Makanan murah banget dan rasanya lumayan enak, working space nya adem, sunyi dan terang. deket bgt sama UB juga', 5, 'makanan_minuman', 'positif', 'benar', NULL, NULL, '2026-10-26 03:54:04'),
  (41, 41, 'Tempatnya sungguh romantis dan cantik', 'Tempatnya sungguh romantis dan cantik. Terletak di tepi sungai dengan pemandangan jembatan yang menyala saat senja, kedai kopi ini sungguh menawarkan suasana yang luar biasa. Kopinya, meskipun begitu, tidak ada yang istimewa, hanya Illy. Namun, lokasinya sendiri patut dikunjungi.', 4, 'suasana', 'positif', 'benar', NULL, NULL, '2026-10-26 04:06:45'),
  (42, 42, 'Tempat cocok buat nongkrong sambil ngopi dan ngemil', 'Tempat cocok buat nongkrong sambil ngopi dan ngemil', 4, 'suasana', 'positif', 'benar', NULL, NULL, '2026-10-26 04:06:45'),
  (43, 43, 'tempat ini cukup ramai', 'Meskipun spesialisasi utamanya adalah kopi, tempat ini juga memiliki makanan enak dengan harga yang wajar. Setelah subuh, tempat ini cukup ramai dan banyak menu sudah habis terjual.', 4, 'suasana', 'netral', 'benar', NULL, NULL, '2026-10-26 04:06:45'),
  (44, 44, 'Numpang ngadem ke tempat ngehits abiiess kekinian yang cozy banget area malang', 'Numpang ngadem ke tempat ngehits abiiess kekinian yang cozy banget area malang..', 5, 'suasana', 'positif', 'benar', NULL, NULL, '2026-10-26 04:06:45'),
  (45, 45, 'Menu beragam kombinasi dari makanan Indonesia', 'Menu beragam kombinasi dari makanan Indonesia, Barat dan Chinnese...ada pilihan RM Padang yang terletak satu kompleks dengan Restoran ini.', 4, 'makanan_minuman', 'netral', 'benar', NULL, NULL, '2026-10-26 04:06:45'),
  (46, 46, 'kami langsung meminta kursi', 'Jujur saya sangat kecewa dengan pelayanan di sini, kami sudah reservasi sebelumnya, tapi saat datang ternyata tempat yang disediakan kehujanan, kami langsung meminta kursi dan meja karena kondisi basah, apalagi saat itu kami sedang puasa dan ingin segera berbuka. Namun, permintaan kami tidak segera ditindaklanjuti (disuruh nunggu tapi gada pergerakan). Bayangkan, dari waktu buka puasa sampai lewat jam 7 malam kami belum juga mendapatkan kursi dan meja, kami sudah menyampaikan ke kasir bahwa kami butuh tempat duduk karena tadi kehujanan, tapi tidak ada kejelasan. Setelah menunggu lama tanpa kepastian, akhirnya kami turun dan menanyakan langsung, barulah disediakan tempat. Kami baru bisa makan sekitar setengah 8 malam. Itu pun dengan kondisi nasi terkena air hujan dan sudah dingin, ayamnya juga kurang berasa, ditambah pelayanan terkesan tidak peduli, pengalaman berbuka puasa kami jadi sangat tidak menyenangkan, saaat saya chat untuk menanyakan soal kursi, malah disuruh “jangan menyalahkan keadaan". Sebagai pelanggan, apalagi sudah reservasi dan sedang dalam kondisi puasa, tentu kami berharap pelayanan yang lebih sigap dan empati. Semoga ke depannya bisa lebih memperhatikan kenyamanan dan kepuasan pelanggan agar kejadian seperti ini tidak terulang lagi🙂‍↕️🙏', 1, 'suasana', 'negatif', 'benar', NULL, NULL, '2026-10-26 04:06:45'),
  (47, 47, 'Dulu bisa kerja thesis sampai pagi disini', 'Dulu bisa kerja thesis sampai pagi disini... Sekarang udah ga bisa lagi... Jam 21 sudah off yang dalem...', 5, 'fasilitas_wfc', 'positif', 'benar', NULL, NULL, '2026-10-26 04:06:45'),
  (48, 48, 'Tempatnya pw 👍 …', 'Tempatnya pw 👍 …', 5, 'suasana', 'positif', 'benar', NULL, NULL, '2026-10-26 04:06:45'),
  (49, 49, 'Americano icenya enak', 'Americano icenya enak, legit banget, asemnya balanced ma pahitnya Mas Dian ma pak Diki managernya baek banget, besok saya back lg utk ajak rombongan O ya, kekurangannya cuma 1 kurang bersih, bawah meja msih ada sampah dan beres2 sisaan customer kurang gercep Menu BF cukup lengkap, lumayan gesit pas bawa rombongan, orderan ga ada yg salah, platting jg rapi ga krn buru2 trus jadi jelek, makasih banyak pak Diki en mas Dian, the best lah', 4, 'makanan_minuman', 'positif', 'benar', NULL, NULL, '2026-10-26 04:06:45'),
  (50, 50, 'tmptnya comfy buat ngobrol buat nugas', 'rock salt breadnha juara, tmptnya comfy buat ngobrol buat nugas', 5, 'fasilitas_wfc', 'positif', 'benar', NULL, NULL, '2026-10-26 04:06:45'),
  (51, 51, 'Makanan terakhir disajikan 1 jam sejak order', 'Penyajian makanan sangat lama, sekitar 30 menit untuk makanan pertama. Makanan juga tidak disajikan barengan, selang 10-15 menit per orderan. Makanan terakhir disajikan 1 jam sejak order. Untuk harga segitu, makanan nya biasa saja, minuman dan dessert oke. Grilled barbecue chicken steak sangat tidak recommended, disajikan gosong, dan salted egg dori rice terlalu asin dan berminyak. Sangat tidak worthy untuk harga yg dibayarkan. Pelayanan sangat buruk. Ada waitress bernama Ana yg attitude nya nol, cara menghandle komplain juga minus, dan sejujurnya si Ana ini yg benar2 ruin the whole mood for the dinner. Saat ditanya mengapa orderan kami datang nya tidak barengan, jawabnya karena proses masak nya beda2. Kenapa meja sebelah dori nya dateng barengan padahal kita order setengah jam lebih dulu? Jawab nya, ya memang proses nya lama kak. Kenapa chicken steak nya banyak yg hitam2 gini ya? Jawabnya, ya mungkin api nya terlalu besar kak. Berarti ini gosong? Jawab nya, nggak terlalu gosong kak, itu ada bagian yg putih kan. (Setelah bbrp saat..) Makanan nya mau sy tukar kak? (Saya liat jam sdh jam stg 9 malam) berapa lama kalau ditukar yg baru? "Sekitar 20 menit kak" Ya sudah nggak usah, sy sudah lapar mbak. And then, she just went away without apologizing at all.', 1, 'makanan_minuman', 'negatif', 'benar', NULL, NULL, '2026-10-26 04:06:45'),
  (52, 52, 'enak juga sih', 'Pernah ke sini sekali dan waktu itu coba cold brew white, enak juga sih. Terus, tempatnya bagus dan rapi, barnya juga keren. Ada tempat duduk indoor dan outdoor. Tempatnya depan jalan besar , jadi mudah ditemukan dan mudah didatangi.', 4, 'makanan_minuman', 'positif', 'benar', NULL, NULL, '2026-10-26 04:06:45'),
  (53, 53, 'Dirty matcha was pretty good', 'Dirty matcha was pretty good. Golden time nya 86 detik, diminum setelahnya pun masih enak. Food was great and have a lot of options. Pelayanannya cepat. Tempatnya bersih and surprisingly have a lot of seat (ada meeting room juga). Nice ambience, bisa untuk nugas atau WFC.', 5, 'makanan_minuman', 'positif', 'benar', NULL, NULL, '2026-10-26 04:06:45'),
  (54, 54, 'Kopinya bener2 kopi sejati', 'Kopinya bener2 kopi sejati', 5, 'makanan_minuman', 'positif', 'benar', NULL, NULL, '2026-10-26 04:06:45'),
  (55, 55, '3. Toilet nya rusak', 'Lebih di EVALUASI lagi untuk KARYAWAN nya yang PEREMPUAN. Karena selama saya nongkrong bersama Teman Teman. Sikap,Perilaku,Attitude nya SANGAT SANGAT TIDAK SOPAN. Jadi saya mohon dengan kesadaran nya. Saya jauh jauh dari luar kota datang ke Cafe Nakoa Bondowoso pingin menu nya apa saja. Tapi 1. Pelayanan kurang Maksimal. 2. Pada waktu itu kondisi Hujan dan di dalam penuh, saya di luar teryata di luar Air nya masih kena aja. 3. Toilet nya rusak. 4. Mushola tidak ada. 5. Jalan untuk naik turun licin 6. Meja mau di tempati masih kotor. Lebih cerdas sedikit lebih cermat lebih cepat kalau melayani customer jangan lemot dan banyak becanda dan lebih sigap lagi.', 1, 'fasilitas_wfc', 'negatif', 'benar', NULL, NULL, '2026-10-26 04:06:45'),
  (56, 56, 'Tempat terbaik', 'Tempat terbaik, sederhana namun kuat.', 5, 'suasana', 'positif', 'benar', NULL, NULL, '2026-10-26 04:06:45'),
  (57, 57, 'udah reservasi dari minggu minggu lalu cuma makanan sampe 1 jam setelah buka puasa belum disajikan sama sekali', 'jujurrr pertama kali makan disini dibulan ramadhan padahal udah reservasi dari minggu minggu lalu cuma makanan sampe 1 jam setelah buka puasa belum disajikan sama sekali, cuma disuruh tunggu tunggu doang sama pelayannya padahal orang ingin membatalkan puasanya (tolong diperbaiki lagi sistemnya supaya sebelum buka puasa makanan sudah tersedia di meja apalagi kami sudah reservasi dari jauh jauh hari', 1, 'makanan_minuman', 'negatif', 'benar', NULL, NULL, '2026-10-26 04:06:45'),
  (58, 58, 'buat ramean nongkrong sama temen juga ok', 'Pelayanan ok si, tempatnya luas depan, tengah sama belakang, area indoor sama outdoor juga ok, buat ramean nongkrong sama temen juga ok, minuman harganya affordable si ya standart cafe di malang lah start from 20k an, wifi nya kenceng, cuma … Lainnya', 4, 'suasana', 'positif', 'benar', NULL, NULL, '2026-10-26 04:06:45'),
  (59, 59, 'Minuman nya juga enak Lainnya', 'Tempat nya nyaman banget dan worth it buat sambil ngerjain tugas atau skripsian. Minuman nya juga enak Lainnya', 5, 'makanan_minuman', 'positif', 'benar', NULL, NULL, '2026-10-26 04:06:45'),
  (60, 60, 'Untuk kamu yang mau nongki with view citylight oke banget sih disini', 'Untuk kamu yang mau nongki with view citylight oke banget sih disini, cuman menurutku untuk menu di pesen kopi kurang oke, suamik pesen kopi butter tapi rasanya aneh banget, dan tidak ada pilihan hot or cold Lalu tidak ada menu snack nya, dibawah hanya menu per-kue-an dan makanan berat', 4, 'suasana', 'positif', 'benar', NULL, NULL, '2026-10-26 04:06:45'),
  (61, 61, 'Harga lumayan cuman ok lah buat matcha latte Lainnya', 'Best sih matcha nya, diarahin juga pas pesen, jadi bisa disesuaikan sesuai selera. Harga lumayan cuman ok lah buat matcha latte Lainnya', 5, 'makanan_minuman', 'positif', 'benar', NULL, NULL, '2026-10-26 04:09:17'),
  (62, 62, 'Tp gak suka bgt sama pemilihan musik/playlistnya', 'Nasi goreng adalah menu makanan andalan mereka, rasanya gak perlu diragukan lg enakkk dan manteppp deh. Baru coba nasi goreng jawa dan nasi goreng hongkong enak semua, porsinya agak banyak, bumbunya pas, yg paling aku suka acarnya enak bgt🫠 Kalo nasi goreng jawa lebih kerasa bumbu rempahnya, kalo nasi goreng hongkong rasanya soft gak terlalu banyak bumbu dan lebih banyak komposisi sayurnya. Minuman juice enak semua, rasanya manis pas dan kerasa banyak susunya. Ada ukuran L dan M. Mantepp bgt👍🏻 Untuk pelayanan tolong dong langsung dikasih tau menu apa saja yg kosong, jangan ps udah pilih makanan harus balik lg dan pilih lg karena menu kosong, biar gak memakan waktu🥲 Suasana tempat enak nyaman, tempat duduk sofa di dalam empuk. Tp gak suka bgt sama pemilihan musik/playlistnya. Waktu ke sana lagunya gak jelas, lagu2 remix dj yg ada di yutup2 mana kencenggg suaranya malah bikin gak nyaman dan kepala pusing. Saran: tolong dipilah pilih lagi playlist yg cocok utk di cafe yg suasananya cocok sama tempatnya, jgn asal pilih lagu2 random dan gak jelas suara nyanyi apa soalnya ketutup musiknya yg jedag jedug malah berasa kaya lg dugem pdhl posisinya lg makan siang😭😭😭 Gak semua lagu viral lagu jedag jedug itu cocok dijadikan playlist apalagi di restoran makan, tolong dipertimbangkan lagi ya! Parkir gratis tp kalo mobil agak susah soalnya sempit.', 4, 'suasana', 'negatif', 'benar', NULL, NULL, '2026-10-26 04:09:17'),
  (63, 63, 'Mereka menyajikan makanan lezat dengan harga terjangkau (untuk penduduk lokal)', 'Mereka menyajikan makanan lezat dengan harga terjangkau (untuk penduduk lokal).', 4, 'makanan_minuman', 'positif', 'benar', NULL, NULL, '2026-10-26 04:09:17'),
  (64, 64, 'masa iya udah bayar parkir tp parkirannya ga aman', 'Tolong dong buat yg jaga parkiran di tegur, masa iya udah bayar parkir tp parkirannya ga aman, naro makanan di cantolin di motor, malah hilang', 1, 'harga', 'negatif', 'salah', 'negatif', 'bukan harga itu tapi pelayanan kang parkirnya menghilangkan makanan pelanggan di motor pdhal parkirnya bayar', '2026-10-26 04:09:17'),
  (65, 65, 'Suasana modern', 'Kami memesan cappuccino panas, matcha dingin, dan americano dingin. Semuanya sangat lezat! Suasana modern dan nyaman. Keterampilan barista yang berbakat. Kami pasti akan kembali! :) Lainnya', 5, 'suasana', 'positif', 'benar', NULL, NULL, '2026-10-26 04:09:17'),
  (66, 66, '- krispi ciken ny enak teksturny', '- Milo 17k rasa hambar banyak air. Mngkin krna mnta less ice. - krispi ciken ny enak teksturny. - ciken katsu bumbu default. - PARKIR MOBIL 5K, pake jalan umum pulak. - Lattes nya enak. - tempatnya bagus, cozy + masih baru. - yg kerja ramah2. Gk butuh good looking.', 2, 'makanan_minuman', 'positif', 'benar', NULL, NULL, '2026-10-26 04:09:17'),
  (67, 67, 'service yang luar biasa @genrossi', 'Cafe yang indah bagaikan surga dunia,pemandangan dan service yang luar biasa @genrossi,the bestyyyttt😱🥰', 5, 'pelayanan', 'positif', 'benar', NULL, NULL, '2026-10-26 04:09:17'),
  (68, 68, 'Rekomendasi sekali kl cari tempat berkonsep semi outdoor', 'Rekomendasi sekali kl cari tempat berkonsep semi outdoor, rindang, dan disuguhi view rel kereta api. Minusnya minim colokan dan kurang proper utk ngerjain tugas, pas kesana jg wifinya mati.', 4, 'suasana', 'positif', 'benar', NULL, NULL, '2026-10-26 04:09:17'),
  (69, 69, 'bisa bayar pake QRIS juga', 'Harga menunya standar, pelayanan ramah, bisa bayar pake QRIS juga. Speed wifi-nya lumayan kencang dan ada colokan di tiap meja. Kalau kesini pas sore atau lagi hujan enak, adem suasananya.', 5, 'harga', 'positif', 'benar', NULL, NULL, '2026-10-26 04:09:17'),
  (70, 70, 'enak buat janjian', 'Tempatnya bagus dan enak buat janjian, parkir lumayan luas, mushola bersih. Untuk goweser, ga ada', 5, 'makanan_minuman', 'positif', 'benar', NULL, NULL, '2026-10-26 04:09:17'),
  (71, 71, 'bisa untuk sekedar nongkrong', 'Tempatnya nyaman,ada smoking areanya juga,bisa untuk sekedar nongkrong,meeting,,Menu2 nya beragam,untuk kopi juga tersedia berbagai macam jenis kopi indonesia dan dari luar negeri juga ada,untuk makanan menurut saya cenderung ke snacking ya,soal harga start dari 40anK,ok excelso sukses ya 👍 … Lainnya', 5, 'suasana', 'positif', 'benar', NULL, NULL, '2026-10-26 04:09:17'),
  (72, 72, 'Ada musik yg slalu on', 'Ada musik yg slalu on. Harganya murahhhh bgt. Close order jam 12, tutup jam 2. Pelayanannya juga ramah. Terang ruangannya bisa buat nugas juga', 5, 'suasana', 'netral', 'benar', 'positif', NULL, '2026-10-26 04:09:17'),
  (73, 73, 'Semoga rasa nikmatnya tetep konsisten', 'Awalnya coba coba, Alhamdulillah dari sekian banyak coba beli kopi di lapak shopee, kali menemukan rasa kopi yang cocok buat konsumsi sendiri. Insya Allah bakal berlangganan. Semoga rasa nikmatnya tetep konsisten.', 5, 'makanan_minuman', 'positif', 'benar', NULL, NULL, '2026-10-26 04:09:17'),
  (74, 74, 'Tempatnya nyaman jika sore hari', 'Pesanan yang datang sesuai dengan foto yang disajikan. Tempatnya nyaman jika sore hari. Kalau datang kesini malam hari usahakan pakai jaket agar tidak kedinginan. --------------------------------------------------------------- Update: 27 oktober 2022 -Tempat minumannya berubah jadi cup plastik. :( sayang sekali menurunkan estetikanya. -Pesanan diambil sendiri. Kalau dulu diantar. -kamar mandinya seram', 5, 'suasana', 'positif', 'benar', NULL, NULL, '2026-10-26 04:09:17'),
  (75, 75, 'nyaman sekali untuk dine in', 'Enak, tp porsi menengah ke kecil untuk menu sarapan nasi liwet solonya. Tempat cantik dan nyaman sekali untuk dine in. Sayang parkir sangat terbatas..', 5, 'suasana', 'positif', 'benar', NULL, NULL, '2026-10-26 04:09:17'),
  (76, 76, 'PR nya Klo bawa mobil susah parkir', 'Kopi enak, mantap. salt bread enak. Blm pernah coba makanan beratnya. Tempat nyaman buat ngbrol / wfc (ada area indoor yg ac nya adem pol). PR nya Klo bawa mobil susah parkir. Klo pagi banyak yg finishan lari / sepeda disini Lainnya', 5, 'fasilitas_wfc', 'negatif', 'benar', NULL, NULL, '2026-10-26 04:09:17'),
  (77, 77, 'mencairkan suasana dengan mengupas buku bacaan yg tersedia disana', 'Cocok untuk nongkrong bareng teman, mencairkan suasana dengan mengupas buku bacaan yg tersedia disana', 3, 'suasana', 'netral', 'salah', 'positif', NULL, '2026-10-26 04:09:17'),
  (78, 78, 'Ambience cafenya ngebuat kita berasa lagi di rumah', 'Cafe yang cukup nyempil di wilayah tlogomas/dinoyo. Ambience cafenya ngebuat kita berasa lagi di rumah, area parkirnya cukup luas dan makanan dan minumanya juga enak. Lainnya', 5, 'suasana', 'positif', 'benar', NULL, NULL, '2026-10-26 04:09:17'),
  (79, 79, 'worth it🤩 Yuk cobain kesini', 'ARAH COFFEE AKHIRNYA BUKA DI MALANG☕️🫵🏻 Arah Coffee yang dulunya ada di Jakarta sekarang buka cabang di Malang dengan konsep cafenya yang super aesthetic dengan tempat yang luas, banyak colokan, bangkunya nyaman semua apalagi ada sofa, pilihan snack dan minumannya bervariasi dengan harga yang standar tapi worth it🤩 Yuk cobain kesini, cocok buat nugas, WFC, kumpul-kumpul dan nongkrong🙌🏻', 5, 'harga', 'positif', 'benar', NULL, NULL, '2026-10-26 04:09:17'),
  (80, 80, 'MAHAL dg rasa yg dibwh standard … Lainnya', 'Utk ukuran kota Mlg yg gudangnya cafe..cafe ini biasa sj, cmn jual view yg jg biasa sj utk kota Mlg.. Yg luar biasa harga makanan & minumannya..MAHAL dg rasa yg dibwh standard … Lainnya', 2, 'makanan_minuman', 'negatif', 'benar', NULL, NULL, '2026-10-26 04:09:17'),
  (81, 81, 'suasana rileks jauh dari kebisingan', 'Tempat nyaman, adem, bersih, rapi, suasana rileks jauh dari kebisingan. Minusnya pelayan nga beri penjelasan lengkap ke pelanggan soal menu & kurang peka apa yang dibutuh pelanggan. Karena banyak juga pelanggan yang baru pertama kali kesitu.', 5, 'suasana', 'positif', 'benar', NULL, NULL, '2026-10-26 04:13:13'),
  (82, 82, 'suasananya bagus buat nugas', 'suasananya bagus buat nugas', 5, 'fasilitas_wfc', 'positif', 'benar', NULL, NULL, '2026-10-26 04:13:13'),
  (83, 83, 'Enak banget specialtynya 😍😍😍 …', 'Enak banget specialtynya 😍😍😍 …', 5, 'makanan_minuman', 'positif', 'benar', NULL, NULL, '2026-10-26 04:13:13'),
  (84, 84, 'mengusung konsep klasik heritage gitu lah karena tempatnya kayak bangunan lama gitu', 'Tempatnya di kios kios gitu, mengusung konsep klasik heritage gitu lah karena tempatnya kayak bangunan lama gitu, ada dua lantai sayangnya waktu kesana rame bangett dan panas, dari segi kebersihan tempatnya menurut aku agak kurangnya, dari segi makanan enak enak kok kopinya juga enak Lainnya', 4, 'suasana', 'negatif', 'benar', NULL, NULL, '2026-10-26 04:13:13'),
  (85, 85, 'HATI2 YANG LAPER YA 😙😙 SINTING INI TEMPAT', 'PESAN MAKAN DARI JAM 6 SAMPEK JAM SET8 BELUM DI MASAK2 !! BODOH BGT PELAYANAN E.. NGURUSI ANJING DOANG.. DI TANYAI BOLAK BALIK GAK DI MASAK2IN.. HEBAT BANGET ? DAYA TARIK CUMA ANJING.. PELAYANAN AMPAS.. HATI2 YANG LAPER YA 😙😙 SINTING INI TEMPAT.. UDAH SERVICE AMPAS.. KENA SERVICE CHARGE PULA.. GILA HATI2 YANG KESINI YA.. APALAGI YANG PUNYA MAAG.. GA RECOMMENDATIONS BGT.. ITU YG REVIEW BAGUS DIBAYAR BERAPA SAMA TEMPAT INI ? 😂😂', 1, 'suasana', 'negatif', 'benar', NULL, NULL, '2026-10-26 04:13:13'),
  (86, 86, 'ingin menikmati kopi yang nikmat', 'Tempat yang wajib dikunjungi saat Anda berada di Malang dan ingin menikmati kopi yang nikmat! Mereka juga menyediakan camilan seperti Roti Pisang, Croissant, Quiche, dll. jika Anda sedang mencari sesuatu untuk dimakan di sana. Saya sangat … Lainnya', 5, 'makanan_minuman', 'positif', 'benar', NULL, NULL, '2026-10-26 04:13:13'),
  (87, 87, 'Konsep open kitchen jadi tau pesanan sedang dikerjakan', 'Kesini lagi dengan nama tempat berbeda. Pas malming tapi tempat masih sepi. Sayangnya kejunya habis. Akhirnya pesan yg lain. Konsep open kitchen jadi tau pesanan sedang dikerjakan dan semerbak bau bumbu² nya saat diolah menggoda selera. Alhamdulillah rasa enak dan rekom kalo kesini lagi. Buat yg mau nugas ato nongkrong lama tersedia steker / colokan.', 5, 'suasana', 'positif', 'benar', NULL, NULL, '2026-10-26 04:13:13'),
  (88, 88, 'lantai 1 bagian luar diperuntukkan untuk merokok', 'Bangunan ini terdiri dari dua lantai, dengan lantai 2 dan lantai 1 bagian luar diperuntukkan untuk merokok, tempat yang bagus untuk bekerja atau sekadar mengobrol santai dengan teman.', 5, 'kebersihan', 'positif', 'benar', NULL, NULL, '2026-10-26 04:13:13'),
  (89, 89, 'adem dan spacious', 'good food, good vibes, nyaman buat wfc, banyak colokan, adem dan spacious', 5, 'suasana', 'positif', 'benar', NULL, NULL, '2026-10-26 04:13:13'),
  (90, 90, 'Silahkan dapat menginformasikan keluhannya melalui layanan Customer Service kami … Lainnya', 'Halo Kak, terima kasih atas review serta kunjunganya. Saran, kritik dan komentar dari kakak sangat kami perlukan agar pelayanan kami menjadi lebih baik lagi. Silahkan dapat menginformasikan keluhannya melalui layanan Customer Service kami … Lainnya', 5, 'pelayanan', 'positif', 'salah', 'netral', 'ini balesan dari kafenya njirr bukan ulasan pelanggan', '2026-10-26 04:13:13'),
  (91, 91, 'terjangkau ☕️👍 …', 'kopinya enak, harga tergolong cukup murah dan terjangkau ☕️👍 …', 5, 'harga', 'positif', 'benar', NULL, NULL, '2026-10-26 04:13:13'),
  (92, 92, 'Satsett ga pake jutek', 'Nuker shopee vip psl dekat rumah ga pernah ada yg bisa walaupun udah pagi², tapi di sini bisaa jam 6an pagi gitu. Satsett ga pake jutek, ga pake 1001 alasan/error. Semoga mas baristanya selalu dipermudah segala urusan hidupnya, mengalir deras rezekinya, sehat selalu 🤲🏻 … Lainnya', 5, 'pelayanan', 'positif', 'benar', NULL, NULL, '2026-10-26 04:13:13'),
  (93, 93, 'Salah satu kopi terenak di Malang', 'Salah satu kopi terenak di Malang. Harga diatas rata2.', 5, 'makanan_minuman', 'positif', 'benar', NULL, NULL, '2026-10-26 04:13:13'),
  (94, 94, 'Saat kamu minum kopi', 'Saat kamu minum kopi, kamu menemukan suasana yang nyaman hehe', 5, 'makanan_minuman', 'positif', 'benar', NULL, NULL, '2026-10-26 04:13:14'),
  (95, 95, 'harga nya kaki lima', 'minuman coklatnya mantap...harga nya kaki lima, pemandangan malam hari nya keren demgan backround gunung yg indah', 5, 'harga', 'positif', 'benar', NULL, NULL, '2026-10-26 04:13:14'),
  (96, 96, 'dan manis jadi satu', 'Pilihan menu sangat beragam. Saya coba minuman matcha klasiknya enak, creamy, gurih, dan manis jadi satu. Terdapat banyak', 5, 'makanan_minuman', 'positif', 'benar', NULL, NULL, '2026-10-26 04:13:14'),
  (97, 97, 'tempatnya udah gk seenak dulu', 'Menu mahal, tempatnya udah gk seenak dulu', 3, 'suasana', 'netral', 'salah', 'negatif', 'udah ga seenak dulu brrti sekarang gaenak', '2026-10-26 04:13:14'),
  (98, 98, 'spaghetti bolognese-nya enak', 'spaghetti bolognese-nya enak, recommended tempatnya nggak terlalu luas, tapi penataannya oke pelayanannya bagus Lainnya', 5, 'makanan_minuman', 'positif', 'benar', NULL, NULL, '2026-10-26 04:13:14'),
  (99, 99, 'Nunggu orderan 1jam', 'Sebenarnya suka pizza disini enak banget. Tapi hari ini agak sebel sih. Nunggu orderan 1jam. Padahal yg dateng setelah kita kok udah dapet minuman duluan. Udah gitu keponakan aku baru selesai makan slice pizza terakhir udah didatengin karyawan nya mau beresin nampan pizza nya. Emang bagian tengah yg ada lava cheese nya gk boleh dihabisin kah? Keponakanku suka banget padahal.', 3, 'pelayanan', 'netral', 'salah', 'negatif', 'nunggu 1 jam itu termasuk lamaa', '2026-10-26 04:13:14'),
  (100, 100, 'Harga masih oke mengingat cafenya dituliskan buka 24 jam (mungkin sebelum pandemi)', 'Cafe ini cocoknya untuk mahasiswa yang ngerjain tugas/nongkrong santai tanpa ootd dll. Harga masih oke mengingat cafenya dituliskan buka 24 jam (mungkin sebelum pandemi) dan free wifi sehingga sangat worth it untuk nugas semalam suntuk. Kentangnya 12ribu, enak2 aja walau dingin dan leyot tp cukup membuat kenyang sebagai teman nugas/ngobrol. Kondisi waktu saya datang cafenya seperti kotor entah di mata saya aja atau gimana, lantai spt kotor, ada serangga mati dan disemutin di kursi putih yang nempel dgn dinding tp tidak dibersihkan.. kardus2 stok barang terpampang jelas di depan mata, bagi saya agak kurang enak dilihat tp mungkin emg ga ada tempat lagi jadi gapapa.. Kesimpulannya: kalo untuk mahasiswa nugas butuh nongkrong semaleman, cafe ini cocok, kalo mau ootd cantik foto2 dll, sepertinya cafe ini kurang cocok walau di foto2nya terlihat nuansa putih2 bersih dan minimalis karna saat saya ke sana tidak terlihat seperti di foto..', 3, 'harga', 'positif', 'benar', NULL, NULL, '2026-10-26 04:13:14');
